<script setup lang="ts">import{onMounted,ref}from'vue';import{knowledgeApi}from'../api/modules';import{ElMessage}from'element-plus';const docs=ref<any[]>([]),stats=ref({documents:0,chunks:0}),uploading=ref(false),error=ref(''),meta=ref({category:'面试题',technology:'Java',difficulty:'进阶'});async function load(){[docs.value,stats.value]=await Promise.all([knowledgeApi.list(),knowledgeApi.stats()])}async function upload(o:any){uploading.value=true;try{await knowledgeApi.upload(o.file,meta.value);ElMessage.success('文档已完成解析、分块、向量化和入库');await load();o.onSuccess()}catch(e){error.value=(e as Error).message;o.onError(e)}finally{uploading.value=false}}async function remove(id:number){await knowledgeApi.remove(id);await load()}async function reindex(id:number){await knowledgeApi.reindex(id);ElMessage.success('重新向量化完成');await load()}onMounted(()=>load().catch(e=>error.value=e.message))</script>
<template><section class="page-head"><div><h2>RAG 知识库</h2><p>管理员上传后执行 MinIO 保存、Tika 解析、分块、Embedding 和 Elasticsearch 索引。</p></div></section><section class="metric-grid-real"><article class="panel"><small>知识文档</small><strong>{{stats.documents}}</strong></article><article class="panel"><small>知识分块</small><strong>{{stats.chunks}}</strong></article></section><form class="panel upload-panel"><select v-model="meta.category"><option>面试题</option><option>参考答案</option><option>评分标准</option><option>技术文档</option></select><input v-model="meta.technology" placeholder="技术方向"/><select v-model="meta.difficulty"><option>基础</option><option>进阶</option><option>高级</option></select><el-upload :http-request="upload" :show-file-list="false"><button class="primary-button" type="button">{{uploading?'向量化中…':'上传知识文档'}}</button></el-upload></form><div v-if="error" class="error-box">{{error}}</div><section class="panel data-list"><div v-if="!docs.length" class="empty-inline">知识库为空，生成题目和评价前必须先上传文档。</div><div v-for="d in docs" :key="d.id" class="list-row"><span><b>{{d.title}}</b><small>{{d.category}} · {{d.difficulty}} · {{d.createdAt}}</small></span><span class="tag" :class="d.status==='READY'?'green':'orange'">{{d.status}}</span><div><button @click="reindex(d.id)">重新向量化</button><button @click="remove(d.id)">删除</button></div></div></section></template>
